sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
   g_form.getReference('requestor',onAlert); 


      return;
   }


   //Type appropriate comment here, and begin script below

	g_form.getReference('requestor',onAlert);

   function onAlert(vipfield){
	var staus = vipfield.vip ;
	if ( staus == 'true' ){
		//var company = g_form.getControl('requestor');
		g_form.setValue('priority','1');
		//staus.style.backgroundColor = "red";
		var myField = 'requestor';
		var ctrl = g_form.getElement('sys_display.' + g_form.getControl(myField).id);
		ctrl.style.backgroundColor = 'red';

		}
	}

function onAlert(vipfield){
